// entire understand dashboard SPA
//
// Vanilla JS — no React, no transpiler, no build step. Cytoscape.js does the
// graph; everything else is plain DOM. The bootstrap script tag injected by
// the server populates window.__entireUnderstandToken before this file runs;
// every API call sends it as an Authorization: Bearer header. The token is
// never put in URLs or query strings.

(function () {
  "use strict";

  const TOKEN = window.__entireUnderstandToken;
  if (!TOKEN) {
    document.body.textContent = "missing bootstrap token; reload the page";
    return;
  }

  function api(path) {
    return fetch(path, { headers: { Authorization: "Bearer " + TOKEN } }).then(
      function (r) {
        if (!r.ok) throw new Error(path + ": " + r.status);
        return r.json();
      }
    );
  }

  // ---------------------------------------------------------------------------
  // Banner
  // ---------------------------------------------------------------------------
  const banner = document.getElementById("status-banner");
  function showBanner(msg) {
    banner.textContent = msg;
    banner.classList.add("visible");
  }
  function hideBanner() {
    banner.classList.remove("visible");
    banner.textContent = "";
  }

  // ---------------------------------------------------------------------------
  // Side panel
  // ---------------------------------------------------------------------------
  const detail = document.getElementById("detail");
  const dTitle = document.getElementById("d-title");
  const dMeta = document.getElementById("d-meta");
  const dConflictSection = document.getElementById("d-conflict-section");
  const dConflict = document.getElementById("d-conflict");
  const dChildrenSection = document.getElementById("d-children-section");
  const dChildren = document.getElementById("d-children");
  const dCpSection = document.getElementById("d-checkpoints-section");
  const dCheckpoints = document.getElementById("d-checkpoints");
  const dSummarySection = document.getElementById("d-summary-section");
  const dSummary = document.getElementById("d-summary");

  function clearDetail() {
    detail.classList.add("empty");
    dTitle.textContent = "";
    dMeta.textContent = "";
    dConflict.textContent = "";
    dChildren.replaceChildren();
    dCheckpoints.replaceChildren();
    dSummary.replaceChildren();
  }
  clearDetail();

  function showDetail(node) {
    detail.classList.remove("empty");
    dTitle.textContent = node.id;
    const metaParts = [node.type];
    if (node.symbol_kind) metaParts.push(node.symbol_kind);
    if (node.path) metaParts.push(node.path);
    if (node.language) metaParts.push(node.language);
    if (node.line_start) metaParts.push("L" + node.line_start + "-" + node.line_end);
    dMeta.textContent = metaParts.join(" · ");

    // Conflict hint (deterministic, populated by impact endpoint when we add one).
    if (node.conflict_hint) {
      dConflictSection.style.display = "";
      dConflict.textContent = "conflict hint: " + node.conflict_hint;
    } else {
      dConflictSection.style.display = "none";
    }

    // Children: direct contains targets.
    const children = childrenOf(node.id);
    dChildrenSection.style.display = children.length ? "" : "none";
    dChildren.replaceChildren();
    children.forEach(function (c) {
      const li = document.createElement("li");
      const link = document.createElement("a");
      link.href = "#";
      link.textContent = c.label;
      link.addEventListener("click", function (ev) {
        ev.preventDefault();
        focusNode(c.id);
      });
      li.appendChild(link);
      dChildren.appendChild(li);
    });

    // Checkpoint trail.
    const cps = checkpointsTouching(node.id);
    dCpSection.style.display = cps.length ? "" : "none";
    dCheckpoints.replaceChildren();
    cps.forEach(function (cp) {
      const li = document.createElement("li");
      const head = document.createElement("div");
      head.textContent = cp.id;
      li.appendChild(head);
      const meta = document.createElement("div");
      meta.className = "qualifier";
      const parts = [];
      if (cp.created_at) parts.push(cp.created_at);
      if (cp.agent) parts.push(cp.agent);
      if (cp.scope === "file-owner") parts.push("(file-level inferred)");
      meta.textContent = parts.join(" · ");
      li.appendChild(meta);
      const btn = document.createElement("button");
      btn.className = "action";
      btn.textContent = "fetch detail";
      btn.addEventListener("click", function () {
        loadCheckpointDetail(cp.id);
      });
      li.appendChild(btn);
      dCheckpoints.appendChild(li);
    });

    dSummarySection.style.display = "none";
    dSummary.replaceChildren();
  }

  function loadCheckpointDetail(cpID) {
    api("/api/checkpoint/" + encodeURIComponent(cpID))
      .then(function (cp) {
        dSummarySection.style.display = "";
        dSummary.replaceChildren();
        const rows = [
          ["checkpoint_id", cp.checkpoint_id],
          ["strategy", cp.strategy],
          ["branch", cp.branch],
          ["checkpoints_count", cp.checkpoints_count],
          ["session_count", cp.session_count],
        ];
        rows.forEach(function (kv) {
          if (!kv[1]) return;
          const li = document.createElement("li");
          const k = document.createElement("strong");
          k.textContent = kv[0] + ": ";
          li.appendChild(k);
          li.appendChild(document.createTextNode(String(kv[1])));
          dSummary.appendChild(li);
        });
        if (cp.files_touched && cp.files_touched.length) {
          const li = document.createElement("li");
          const k = document.createElement("strong");
          k.textContent = "files (" + cp.files_touched.length + "):";
          li.appendChild(k);
          const ul = document.createElement("ul");
          cp.files_touched.forEach(function (f) {
            const fli = document.createElement("li");
            const link = document.createElement("a");
            link.href = "#";
            link.textContent = f;
            link.addEventListener("click", function (ev) {
              ev.preventDefault();
              focusNode("file:" + f);
            });
            fli.appendChild(link);
            ul.appendChild(fli);
          });
          li.appendChild(ul);
          dSummary.appendChild(li);
        }
      })
      .catch(function (err) {
        showBanner("checkpoint detail failed: " + err.message);
      });
  }

  // ---------------------------------------------------------------------------
  // Graph state
  // ---------------------------------------------------------------------------
  let cy = null;
  let graphData = { nodes: [], edges: [] };
  const nodesByID = new Map();
  const edgesIndexFromTo = new Map(); // from-id -> [edges]
  const edgesIndexToFrom = new Map(); // to-id -> [edges]

  function indexEdge(idx, key, edge) {
    if (!idx.has(key)) idx.set(key, []);
    idx.get(key).push(edge);
  }

  function buildIndex() {
    nodesByID.clear();
    edgesIndexFromTo.clear();
    edgesIndexToFrom.clear();
    graphData.nodes.forEach(function (n) {
      nodesByID.set(n.id, n);
    });
    graphData.edges.forEach(function (e) {
      indexEdge(edgesIndexFromTo, e.from, e);
      indexEdge(edgesIndexToFrom, e.to, e);
    });
  }

  function childrenOf(nodeID) {
    const out = [];
    (edgesIndexFromTo.get(nodeID) || []).forEach(function (e) {
      if (e.type !== "contains") return;
      const child = nodesByID.get(e.to);
      if (!child) return;
      out.push({ id: child.id, label: child.name + (child.symbol_kind ? " · " + child.symbol_kind : "") });
    });
    return out;
  }

  function checkpointsTouching(nodeID) {
    // Direct cp -> file edges.
    const seen = new Set();
    const out = [];
    (edgesIndexToFrom.get(nodeID) || []).forEach(function (e) {
      if (e.type !== "touched_in") return;
      const cp = nodesByID.get(e.from);
      if (!cp) return;
      if (seen.has(cp.id)) return;
      seen.add(cp.id);
      out.push({
        id: cp.name,
        scope: e.scope || "",
        created_at: (cp.attrs && cp.attrs.created_at) || "",
        agent: (cp.attrs && cp.attrs.agent) || "",
      });
    });

    // For symbols: bubble up to owning file's checkpoints (file-owner scope).
    const me = nodesByID.get(nodeID);
    if (me && me.type === "symbol" && me.path) {
      const fileID = "file:" + me.path;
      (edgesIndexToFrom.get(fileID) || []).forEach(function (e) {
        if (e.type !== "touched_in") return;
        const cp = nodesByID.get(e.from);
        if (!cp || seen.has(cp.id)) return;
        seen.add(cp.id);
        out.push({
          id: cp.name,
          scope: "file-owner",
          created_at: (cp.attrs && cp.attrs.created_at) || "",
          agent: (cp.attrs && cp.attrs.agent) || "",
        });
      });
    }
    out.sort(function (a, b) { return (b.created_at || "").localeCompare(a.created_at || ""); });
    return out;
  }

  function focusNode(nodeID) {
    if (!cy) return;
    const ele = cy.getElementById(nodeID);
    if (!ele || ele.empty()) {
      showBanner("node " + nodeID + " not in current view (filter may hide it)");
      return;
    }
    hideBanner();
    cy.elements().removeClass("highlight").removeClass("dim");
    ele.addClass("highlight");
    ele.neighborhood().addClass("highlight");
    cy.elements().difference(ele.neighborhood().union(ele)).addClass("dim");
    cy.animate({
      center: { eles: ele },
      zoom: Math.max(cy.zoom(), 0.9),
    }, { duration: 280 });
    showDetail(nodesByID.get(nodeID));
  }

  // ---------------------------------------------------------------------------
  // Node typing → cytoscape style
  // ---------------------------------------------------------------------------
  const STYLE = [
    {
      selector: "node",
      style: {
        "label": "data(label)",
        "font-size": 10,
        "color": "#1f2937",
        "text-valign": "bottom",
        "text-margin-y": 4,
        "text-wrap": "ellipsis",
        "text-max-width": 110,
        "background-color": "#888",
        "width": 16,
        "height": 16,
        "border-width": 1,
        "border-color": "#fff",
      },
    },
    { selector: 'node[type = "repo"]',       style: { "background-color": "var(--c-repo, #111827)", "width": 28, "height": 28 } },
    { selector: 'node[type = "directory"]',  style: { "background-color": "#94a3b8", "width": 14, "height": 14 } },
    { selector: 'node[type = "file"]',       style: { "background-color": "#4a90e2", "width": 18, "height": 18 } },
    { selector: 'node[type = "symbol"]',     style: { "background-color": "#10b981", "width": 12, "height": 12 } },
    { selector: 'node[type = "package"]',    style: { "background-color": "#6366f1", "shape": "diamond", "width": 14, "height": 14 } },
    { selector: 'node[type = "checkpoint"]', style: { "background-color": "#f59e0b", "shape": "round-rectangle", "width": 14, "height": 12 } },
    { selector: 'node[type = "session"]',    style: { "background-color": "#a855f7", "shape": "round-rectangle", "width": 14, "height": 12 } },
    { selector: 'node[?ghost]',              style: { "background-color": "#dc2626", "border-color": "#7f1d1d", "border-width": 2 } },
    {
      selector: "edge",
      style: {
        "width": 1,
        "line-color": "#cbd5e1",
        "target-arrow-color": "#cbd5e1",
        "target-arrow-shape": "triangle",
        "curve-style": "bezier",
        "opacity": 0.7,
      },
    },
    { selector: 'edge[type = "contains"]',    style: { "line-color": "#9ca3af", "target-arrow-color": "#9ca3af" } },
    { selector: 'edge[type = "imports"]',     style: { "line-color": "#6366f1", "target-arrow-color": "#6366f1", "line-style": "dashed" } },
    { selector: 'edge[type = "touched_in"]',  style: { "line-color": "#fbbf24", "target-arrow-color": "#fbbf24", "opacity": 0.4 } },
    { selector: 'edge[type = "belongs_to"]',  style: { "line-color": "#a855f7", "target-arrow-color": "#a855f7" } },
    { selector: ".highlight",                 style: { "z-index": 999, "border-width": 3, "border-color": "#2563eb" } },
    { selector: "edge.highlight",             style: { "line-color": "#2563eb", "target-arrow-color": "#2563eb", "width": 2, "opacity": 1 } },
    { selector: ".dim",                       style: { "opacity": 0.15 } },
    { selector: ".replay-hidden",             style: { "display": "none" } },
    { selector: ".replay-introduced",         style: { "border-color": "#16a34a", "border-width": 3 } },
    { selector: ".replay-modified",           style: { "border-color": "#f59e0b", "border-width": 2 } },
  ];

  // ---------------------------------------------------------------------------
  // Filters
  // ---------------------------------------------------------------------------
  function activeFilters() {
    const set = new Set();
    document.querySelectorAll('header input[data-filter]').forEach(function (cb) {
      if (cb.checked) set.add(cb.dataset.filter);
    });
    return set;
  }

  function applyFilters() {
    if (!cy) return;
    const allowed = activeFilters();
    cy.batch(function () {
      cy.nodes().forEach(function (n) {
        const t = n.data("type");
        n.style("display", allowed.has(t) ? "element" : "none");
      });
      cy.edges().forEach(function (e) {
        const src = cy.getElementById(e.data("source"));
        const tgt = cy.getElementById(e.data("target"));
        const visible = src && !src.empty() && tgt && !tgt.empty() &&
          src.style("display") !== "none" && tgt.style("display") !== "none";
        e.style("display", visible ? "element" : "none");
      });
    });
  }

  // ---------------------------------------------------------------------------
  // Load + render
  // ---------------------------------------------------------------------------
  function nodeLabel(n) {
    if (n.type === "checkpoint") return n.name.slice(0, 8);
    if (n.type === "session") return "sess";
    if (n.type === "package") return n.name;
    return n.name || n.id;
  }

  function buildElements() {
    const elements = [];
    graphData.nodes.forEach(function (n) {
      elements.push({
        group: "nodes",
        data: {
          id: n.id,
          label: nodeLabel(n),
          type: n.type,
          symbol_kind: n.symbol_kind,
          path: n.path,
          language: n.language,
          ghost: !!(n.attrs && n.attrs.removed),
          attrs: n.attrs || {},
          line_start: n.line_start,
          line_end: n.line_end,
          name: n.name,
        },
      });
    });
    graphData.edges.forEach(function (e) {
      elements.push({
        group: "edges",
        data: {
          id: e.id,
          source: e.from,
          target: e.to,
          type: e.type,
          scope: e.scope || "",
        },
      });
    });
    return elements;
  }

  function relayout() {
    if (!cy) return;
    cy.layout({
      name: "dagre",
      rankDir: "TB",
      nodeSep: 30,
      rankSep: 60,
      animate: true,
      animationDuration: 350,
    }).run();
  }

  function init() {
    Promise.all([api("/api/manifest"), api("/api/graph"), api("/api/timeline")])
      .then(function (results) {
        const m = results[0];
        const graph = results[1];
        const tl = results[2];

        const pill = document.getElementById("manifest-pill");
        pill.textContent =
          (graph.nodes ? graph.nodes.length : 0) + " nodes · " +
          (graph.edges ? graph.edges.length : 0) + " edges · " +
          "semantic " + (m.semantic_status || "?");
        if (m.stale || m.checkpoint_head_changed) {
          showBanner("cache may be stale — run `entire understand build` to refresh");
        }

        graphData = { nodes: graph.nodes || [], edges: graph.edges || [] };
        buildIndex();

        cy = cytoscape({
          container: document.getElementById("cy"),
          elements: buildElements(),
          style: STYLE,
          wheelSensitivity: 0.2,
          minZoom: 0.05,
          maxZoom: 4,
        });
        cy.on("tap", "node", function (evt) {
          const id = evt.target.id();
          focusNode(id);
        });
        cy.on("tap", function (evt) {
          if (evt.target === cy) {
            cy.elements().removeClass("highlight").removeClass("dim");
            clearDetail();
          }
        });

        applyFilters();
        relayout();
        wireSearch();
        wireFilters();
        wireReplay(tl.events || []);

        // If URL fragment matches #area=<id>, focus it once layout settles.
        const fragment = window.location.hash;
        if (fragment.indexOf("#area=") === 0) {
          const target = decodeURIComponent(fragment.slice("#area=".length));
          setTimeout(function () { focusNode(target); }, 600);
        }
      })
      .catch(function (err) {
        document.getElementById("cy").textContent = "load failed: " + err.message;
      });
  }

  // ---------------------------------------------------------------------------
  // Search
  // ---------------------------------------------------------------------------
  function wireSearch() {
    const input = document.getElementById("search");
    let lastMatchID = null;
    input.addEventListener("keydown", function (ev) {
      if (ev.key !== "Enter") return;
      const q = input.value.trim().toLowerCase();
      if (!q) return;
      // Exact-id match first, then substring on name/path.
      let match = null;
      if (nodesByID.has(input.value.trim())) {
        match = nodesByID.get(input.value.trim());
      }
      if (!match) {
        for (const n of nodesByID.values()) {
          if ((n.name && n.name.toLowerCase() === q) ||
              (n.path && n.path.toLowerCase() === q)) {
            match = n;
            break;
          }
        }
      }
      if (!match) {
        for (const n of nodesByID.values()) {
          if ((n.name && n.name.toLowerCase().includes(q)) ||
              (n.path && n.path.toLowerCase().includes(q))) {
            if (n.id === lastMatchID) continue;
            match = n;
            break;
          }
        }
      }
      if (match) {
        lastMatchID = match.id;
        focusNode(match.id);
      } else {
        showBanner("no match for: " + input.value);
      }
    });
  }

  // ---------------------------------------------------------------------------
  // Filter checkboxes
  // ---------------------------------------------------------------------------
  function wireFilters() {
    document.querySelectorAll('header input[data-filter]').forEach(function (cb) {
      cb.addEventListener("change", applyFilters);
    });
    document.getElementById("layout-btn").addEventListener("click", relayout);
    document.getElementById("fit-btn").addEventListener("click", function () {
      if (cy) cy.fit(undefined, 30);
    });
  }

  // ---------------------------------------------------------------------------
  // Replay mode
  // ---------------------------------------------------------------------------
  function wireReplay(events) {
    const btn = document.getElementById("replay-btn");
    const bar = document.getElementById("timeline-bar");
    const slider = document.getElementById("timeline-slider");
    const cur = document.getElementById("timeline-current");
    const total = document.getElementById("timeline-total");
    const exitBtn = document.getElementById("timeline-exit");

    let active = false;
    let chronological = events.slice().sort(function (a, b) {
      return (a.at || "").localeCompare(b.at || "");
    });

    function enter() {
      if (!chronological.length) {
        showBanner("no timeline events; run `entire understand build` against a repo with checkpoints");
        return;
      }
      active = true;
      btn.classList.add("active");
      bar.classList.remove("hidden");
      slider.min = 0;
      slider.max = chronological.length - 1;
      slider.value = chronological.length - 1;
      total.textContent = chronological.length + " events";
      apply(chronological.length - 1);
    }

    function exit() {
      active = false;
      btn.classList.remove("active");
      bar.classList.add("hidden");
      if (!cy) return;
      cy.elements()
        .removeClass("replay-hidden")
        .removeClass("replay-introduced")
        .removeClass("replay-modified");
      applyFilters();
    }

    function apply(idx) {
      if (!cy) return;
      const ev = chronological[idx];
      cur.textContent = (ev && ev.at) ? ev.at : "—";
      // First pass: hide everything, then reveal nodes that have been
      // introduced at or before this index.
      const introducedBefore = new Set();
      for (let i = 0; i <= idx; i++) {
        const e = chronological[i];
        if (e.kind === "introduced" && Array.isArray(e.node_ids)) {
          e.node_ids.forEach(function (n) { introducedBefore.add(n); });
        }
      }
      cy.batch(function () {
        cy.nodes().forEach(function (n) {
          const t = n.data("type");
          if (t === "file" || t === "symbol" || t === "ghost" || (t === "directory" && n.data("ghost"))) {
            n.toggleClass("replay-hidden", !introducedBefore.has(n.id()));
          } else {
            n.removeClass("replay-hidden");
          }
          n.removeClass("replay-introduced").removeClass("replay-modified");
        });

        const justIntroduced = new Set(ev.kind === "introduced" ? (ev.node_ids || []) : []);
        const justModified = new Set(ev.kind === "modified" ? (ev.node_ids || []) : []);
        cy.nodes().forEach(function (n) {
          if (justIntroduced.has(n.id())) n.addClass("replay-introduced");
          if (justModified.has(n.id())) n.addClass("replay-modified");
        });
      });
    }

    btn.addEventListener("click", function () {
      if (active) exit(); else enter();
    });
    exitBtn.addEventListener("click", exit);
    slider.addEventListener("input", function () {
      apply(Number(slider.value));
    });

    // If URL launched with #replay, kick into replay mode after first paint.
    if (window.location.hash === "#replay" || window.location.hash.indexOf("#replay=") === 0) {
      setTimeout(enter, 800);
    }
  }

  init();
})();

