// RegisterHandlers wires the read-only endpoints onto a mux. Exposed so tests
// can drive the server with httptest.NewRecorder + http.Handler directly.
func (s *Server) RegisterHandlers(mux *http.ServeMux) {
	mux.HandleFunc("/", s.serveIndex)
	mux.HandleFunc("/assets/", s.serveAsset)
	mux.HandleFunc("/api/manifest", s.requireToken(s.handleManifest))
	mux.HandleFunc("/api/graph", s.requireToken(s.handleGraph))
	mux.HandleFunc("/api/timeline", s.requireToken(s.handleTimeline))
	mux.HandleFunc("/api/hotspots", s.requireToken(s.handleHotspots))
	mux.HandleFunc("/api/checkpoint/", s.requireToken(s.handleCheckpointDetail))
}

// serveAsset serves the SPA's static assets (app.js, vendor/cytoscape.min.js,
// vendor/dagre.min.js, vendor/cytoscape-dagre.js) from the embedded FS.
//
// The asset routes are intentionally NOT gated by requireToken: they contain
// no user data, only the program logic and the vendored libraries. Token
// gating stays on the API endpoints. The bootstrap script tag (rendered into
// /) is the only place the per-launch token appears server-side, and it is
// HTML-escaped before insertion.
//
// The handler is path-traversal-safe — `path.Clean` collapses `..` and we
// reject any cleaned path that escapes the assets/ subtree.
func (s *Server) serveAsset(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	clean := path.Clean(strings.TrimPrefix(r.URL.Path, "/"))
	if clean == "." || !strings.HasPrefix(clean, "assets/") || strings.Contains(clean, "..") {
		http.NotFound(w, r)
		return
	}
	// Block licensing markdown — informational only, not part of the UI.
	if clean == "assets/vendor/VENDOR-LICENSES.md" {
		http.NotFound(w, r)
		return
	}
	// Block index.html via this path so we can't bypass the token-bootstrap
	// rendering by hitting /assets/index.html directly.
	if clean == "assets/index.html" {
		http.NotFound(w, r)
		return
	}
	data, err := fs.ReadFile(assetsFS, clean)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	switch {
	case strings.HasSuffix(clean, ".js"):
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	case strings.HasSuffix(clean, ".css"):
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
	default:
		w.Header().Set("Content-Type", "application/octet-stream")
	}
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Cache-Control", "no-store")
	if _, err := w.Write(data); err != nil {
		return
	}
}

