// initializer. The asset is bundled at compile time so any error here means
// a build problem worth panicking on at startup rather than a runtime fault.
func mustReadEmbeddedAsset(p string) string {
	data, err := fs.ReadFile(assetsFS, p)
	if err != nil {
		panic("dashboard: missing embedded asset " + p + ": " + err.Error())
	}
	return string(data)
}

