func TestServer_AssetTraversalIsBlocked(t *testing.T) {
	t.Parallel()
	_, h := newHandler(t)

	// Two threat models:
	// 1. Direct-traversal style URLs. http.ServeMux pre-cleans `..` and
	//    issues a 307 redirect to the cleaned path, which then 404s — both
	//    307 and 404 are acceptable here since neither serves the file.
	//    What matters is that no response body ever contains the source.
	// 2. Direct hits on assets we never want exposed (index via /assets/,
	//    license markdown). Those must 404 since http.ServeMux can't help.
	cases := []struct {
		path      string
		wantCodes []int
	}{
		{"/assets/../server.go", []int{http.StatusNotFound, http.StatusMovedPermanently, http.StatusTemporaryRedirect}},
		{"/assets/vendor/../../server.go", []int{http.StatusNotFound, http.StatusMovedPermanently, http.StatusTemporaryRedirect}},
		{"/assets/index.html", []int{http.StatusNotFound}},
		{"/assets/vendor/VENDOR-LICENSES.md", []int{http.StatusNotFound}},
		{"/assets/", []int{http.StatusNotFound}},
		{"/assets/missing.js", []int{http.StatusNotFound}},
	}
	for _, tc := range cases {
		rec := httptest.NewRecorder()
		req := httptest.NewRequestWithContext(t.Context(), http.MethodGet, tc.path, http.NoBody)
		h.ServeHTTP(rec, req)

		ok := false
		for _, want := range tc.wantCodes {
			if rec.Code == want {
				ok = true
				break
			}
		}
		if !ok {
			t.Errorf("%s: status=%d; want one of %v", tc.path, rec.Code, tc.wantCodes)
		}

		// Source-leak guard regardless of status.
		body := rec.Body.String()
		if strings.Contains(body, "package dashboard") || strings.Contains(body, "Vendored third-party assets") {
			t.Errorf("%s: response body leaked source content:\n%s", tc.path, body)
		}
	}
}

