// relayout picks a layout strategy that won't grind the browser. For
// big graphs (many thousands of visible nodes) dagre is too slow, so we
// fall back to cytoscape's built-in `cose` (constraint-based) layout,
// which scales much better. The user can always scope down via filters
// or by clicking "relayout" after narrowing the view.
function relayout() {
  if (!cy) return;
  const visibleCount = cy.nodes(":visible").length;
  let opts;
  if (visibleCount > 1500) {
    opts = { name: "concentric", animate: false, fit: true };
  } else if (visibleCount > 400) {
    opts = { name: "cose", animate: false, fit: true, nodeRepulsion: 4500, idealEdgeLength: 50 };
  } else {
    opts = { name: "dagre", rankDir: "TB", nodeSep: 30, rankSep: 60, animate: true, animationDuration: 350, fit: true };
  }
  cy.layout(opts).run();
}

